// This file is generated by AI.

// 配音配音工作台: API/启动配置 + 配音队列 + 角色列表。
//
// 布局 (自上而下):
// 1. 顶部状态条: GSOV 状态、连接信息、启动/停止、帮助;
// 2. 基础配置: 整合包路径 + 启动方式 + 推理默认值;
// 3. 配音队列: 整体信息与任务列表 (固定高度、内部滚动);
// 4. 角色列表: 搜索 / 新建 / 选择, 以及已启用角色的模型与参考音频。

import {
  Button,
  Dropdown,
  Field,
  Input,
  Option,
  ProgressBar,
  Spinner,
  Tab,
  TabList,
  Textarea,
} from '@fluentui/react-components';
import {
  ArrowClockwiseRegular,
  BookQuestionMarkRegular,
  DismissRegular,
  ErrorCircleRegular,
  FolderOpenRegular,
  PlayRegular,
  StopRegular,
  WrenchRegular,
} from '@fluentui/react-icons';
import { open as openDialog } from '@tauri-apps/plugin-dialog';
import { revealItemInDir } from '@tauri-apps/plugin-opener';
import { useEffect, useState } from 'react';

import type { LaunchConfig } from '../commands/voice';
import { useAppStore } from '../state/store';
import { voiceController } from './controller';
import { formatEta } from './estimate';
import { LANGUAGE_LABELS } from './types';
import { RoleListPanel } from './RoleListPanel';
import { VoiceCacheDialog } from './VoiceCacheDialog';

export function VoiceWorkbench() {
  // 使用说明是独立选项卡, 直接由工作台发起打开
  const onOpenHelp = () => useAppStore.getState().openVoiceGuide();
  const status = useAppStore((state) => state.voiceStatus);
  const logs = useAppStore((state) => state.voiceLogs);
  useAppStore((state) => state.voiceTick);

  const settings = voiceController.getSettings();
  const [rootPath, setRootPath] = useState(settings.launch?.root ?? '');
  const [launch, setLaunch] = useState<LaunchConfig | null>(settings.launch);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [tab, setTab] = useState<'queue' | 'log'>('queue');
  const [changeDialogOpen, setChangeDialogOpen] = useState(false);

  const defaults = settings.defaults;
  const summary = voiceController.queueSummary();

  useEffect(() => {
    if (settings.launch) {
      setRootPath(settings.launch.root);
      setLaunch(settings.launch);
    }
  }, []);

  /** 选择整合包目录并探测 */
  const pickRoot = async () => {
    const selected = await openDialog({ directory: true, multiple: false });
    if (typeof selected !== 'string') return;
    setRootPath(selected);
    setBusy(true);
    setError(null);
    try {
      const config = await voiceController.detect(selected);
      setLaunch(config);
      voiceController.updateSettings({ launch: config });
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  const start = async () => {
    if (!launch) {
      setError('请先选择 GPT-SoVITS 整合包目录');
      return;
    }
    setBusy(true);
    setError(null);
    try {
      await voiceController.startGsv(launch);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setBusy(false);
    }
  };

  const stop = async () => {
    setBusy(true);
    try {
      await voiceController.stopGsv();
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="voice-workbench">
      {/*
        页头只保留标题与说明入口: GSOV 状态由底部状态栏统一承载 (见 StatusBar),
        此处不再重复显示。
      */}
      <div className="voice-workbench-header">
        <div className="voice-workbench-heading">
          <h1>配音工作台</h1>
          <p>配置 GPT-SoVITS 服务与角色库, 管理配音任务队列。</p>
        </div>
        <Button size="small" appearance="secondary" icon={<BookQuestionMarkRegular />} onClick={onOpenHelp}>
          使用说明
        </Button>
      </div>

      {/* -------- 启动配置 -------- */}
      <div className="voice-config">
        <Field label="GPT-SoVITS 整合包目录" className="voice-config-root">
          <div className="voice-root-row">
            <Input value={rootPath} readOnly placeholder="选择包含 api_v2.py 的整合包目录" />
            <Button appearance="secondary" onClick={() => void pickRoot()} disabled={busy}>
              选择…
            </Button>
            <Button
              appearance="subtle"
              title="在文件管理器中打开"
              icon={<FolderOpenRegular />}
              disabled={!rootPath}
              onClick={() => void revealItemInDir(rootPath)}
            />
          </div>
        </Field>

        {/* 启动/停止: 服务状态由底部状态栏承载, 这里只放操作入口 */}
        <div className="voice-launch-actions">
          {status === 'ready' || status === 'starting' ? (
            <Button appearance="secondary" icon={<StopRegular />} disabled={busy} onClick={() => void stop()}>
              停止服务
            </Button>
          ) : (
            <Button appearance="primary" icon={<PlayRegular />} disabled={busy} onClick={() => void start()}>
              启动服务
            </Button>
          )}
        </div>

        {launch && (
          <>
            <div className="voice-config-grid">
              <Field label="启动方式">
                <Dropdown
                  selectedOptions={[launch.mode.kind]}
                  value={modeLabel(launch)}
                  onOptionSelect={(_, data) => {
                    const kind = data.optionValue as LaunchConfig['mode']['kind'];
                    const next: LaunchConfig = {
                      ...launch,
                      mode:
                        kind === 'embedded'
                          ? { kind: 'embedded', program: `${launch.root}\\runtime\\python.exe` }
                          : kind === 'python'
                            ? { kind: 'python', program: 'python' }
                            : { kind: 'command', program: '', args: [] },
                    };
                    setLaunch(next);
                    voiceController.updateSettings({ launch: next });
                  }}
                >
                  <Option value="embedded" text="整合包内置运行时">
                    整合包内置运行时（推荐）
                  </Option>
                  <Option value="python" text="外部 Python">
                    外部 Python（conda / 系统）
                  </Option>
                  <Option value="command" text="自定义命令">
                    自定义命令（bat / ps1 / 可执行文件）
                  </Option>
                </Dropdown>
              </Field>

              <Field label={launch.mode.kind === 'command' ? '命令' : 'Python 解释器'}>
                <Input
                  value={launch.mode.program}
                  onChange={(_, data) => {
                    const next: LaunchConfig = {
                      ...launch,
                      mode: { ...launch.mode, program: data.value } as LaunchConfig['mode'],
                    };
                    setLaunch(next);
                    voiceController.updateSettings({ launch: next });
                  }}
                />
              </Field>

              <Field label="绑定地址">
                <Input
                  value={launch.host}
                  onChange={(_, data) => {
                    const next = { ...launch, host: data.value };
                    setLaunch(next);
                    voiceController.updateSettings({ launch: next });
                  }}
                />
              </Field>

              <Field label="端口">
                <Input
                  value={String(launch.port)}
                  onChange={(_, data) => {
                    const port = Number.parseInt(data.value.replace(/[^0-9]/g, ''), 10) || 9880;
                    const next = { ...launch, port };
                    setLaunch(next);
                    voiceController.updateSettings({ launch: next });
                  }}
                />
              </Field>
            </div>

            {launch.mode.kind === 'command' && (
              <Field label="命令参数（每行一个）">
                <Textarea
                  value={launch.mode.args.join('\n')}
                  resize="vertical"
                  onChange={(_, data) => {
                    const next: LaunchConfig = {
                      ...launch,
                      mode: { ...launch.mode, args: data.value.split('\n').filter(Boolean) } as LaunchConfig['mode'],
                    };
                    setLaunch(next);
                    voiceController.updateSettings({ launch: next });
                  }}
                />
              </Field>
            )}

            <div className="voice-config-grid">
              <Field label="控制脚本（相对整合包根）">
                <Input
                  value={launch.script}
                  onChange={(_, data) => {
                    const next = { ...launch, script: data.value };
                    setLaunch(next);
                    voiceController.updateSettings({ launch: next });
                  }}
                />
              </Field>
              <Field label="推理配置（相对整合包根）">
                <Input
                  value={launch.inferConfig}
                  onChange={(_, data) => {
                    const next = { ...launch, inferConfig: data.value };
                    setLaunch(next);
                    voiceController.updateSettings({ launch: next });
                  }}
                />
              </Field>
            </div>
          </>
        )}

        {/*
          推理默认值: 只保留真正需要在工作台层面决定的项。
          因此都不在此处暴露。
        */}
        <div className="voice-config-grid">
          <Field label="默认语言" className="voice-field-narrow">
            <Dropdown
              className="voice-control-narrow"
              selectedOptions={[defaults.language]}
              value={LANGUAGE_LABELS[defaults.language] ?? defaults.language}
              onOptionSelect={(_, data) =>
                voiceController.updateSettings({ defaults: { ...defaults, language: data.optionValue ?? 'auto' } })
              }
            >
              {Object.entries(LANGUAGE_LABELS).map(([code, label]) => (
                <Option key={code} value={code} text={label}>
                  {label}
                </Option>
              ))}
            </Dropdown>
          </Field>
        </div>

        {error && (
          <p className="voice-error">
            <ErrorCircleRegular /> {error}
          </p>
        )}
      </div>

      {/* -------- 队列 / 日志 -------- */}
      <div className="voice-queue-section">
        <div className="voice-queue-head">
          <TabList selectedValue={tab} onTabSelect={(_, data) => setTab(data.value as 'queue' | 'log')}>
            <Tab value="queue">配音队列</Tab>
            <Tab value="log">运行日志</Tab>
          </TabList>
          <span className="voice-queue-summary">
            待处理 {summary.pending}（测试 {summary.pendingTest} · 生成 {summary.pendingGenerate}）
            {summary.running > 0 && ` · 运行中 ${summary.running}`}
            {summary.pending + summary.running > 0 && ` · 预计 ${formatEta(summary.etaMillis)}`}
            {summary.pendingGenerate > 0 && summary.pendingTest > 0 && (
              <span className="voice-queue-hint">
                （立即队列将把生成任务延后 {formatEta(summary.immediateDelayMillis)}）
              </span>
            )}
          </span>
          <span className="voice-actions-spacer" />
          <Button
            size="small"
            appearance="subtle"
            title="清理未被任何场景引用的缓存音频"
            icon={<WrenchRegular />}
            onClick={() => setChangeDialogOpen(true)}
          >
            缓存与引用
          </Button>

          <Button
            size="small"
            appearance="subtle"
            title="清空已完成的任务"
            icon={<DismissRegular />}
            onClick={() => {
              voiceController.clearFinishedTasks();
              setTab('queue');
            }}
          >
            清理
          </Button>
        </div>

        {tab === 'queue' ? (
          <div className="voice-queue-list">
            {voiceController.allTasks().length === 0 && (
              <p className="voice-dialog-empty">队列为空。在场景卡的配音模式中点击「测试」或「生成」。</p>
            )}
            {voiceController.allTasks().map((task) => (
              <div key={task.id} className={`voice-task ${task.status}`}>
                <span className={`history-kind ${task.kind}`}>{task.kind === 'test' ? '测试 x4' : '生成 x32'}</span>
                <span className="voice-task-text">{task.text || '（空）'}</span>
                <span className="voice-task-character">{task.characterName}</span>
                <span className="voice-task-status">
                  {task.status === 'pending' && '等待中'}
                  {task.status === 'running' && (
                    <>
                      <Spinner size="extra-tiny" /> 生成中
                    </>
                  )}
                  {task.status === 'done' && '已完成'}
                  {task.status === 'failed' && <span className="voice-error">{task.error}</span>}
                  {task.status === 'canceled' && '已取消'}
                </span>
                {task.status === 'running' && <ProgressBar className="voice-task-progress" />}
              </div>
            ))}
          </div>
        ) : (
          <div className="voice-log">
            {logs.length === 0 && <p className="voice-dialog-empty">暂无日志。</p>}
            {logs.map((line, index) => (
              <div key={index} className="voice-log-line">
                {line}
              </div>
            ))}
            <Button
              size="small"
              appearance="subtle"
              icon={<ArrowClockwiseRegular />}
              onClick={() => void voiceController.syncStatus()}
            >
              刷新
            </Button>
          </div>
        )}
      </div>

      {/* -------- 角色列表 -------- */}
      <RoleListPanel onOpenHelp={onOpenHelp} />

      <VoiceCacheDialog open={changeDialogOpen} onClose={() => setChangeDialogOpen(false)} />
    </div>
  );
}

function modeLabel(launch: LaunchConfig): string {
  switch (launch.mode.kind) {
    case 'embedded':
      return '整合包内置运行时（推荐）';
    case 'python':
      return '外部 Python（conda / 系统）';
    default:
      return '自定义命令（bat / ps1 / 可执行文件）';
  }
}
